```javascript
function sortJsonByKeys(jsonObj) {
  // Convert JSON object to array of key-value pairs
  const entries = Object.entries(jsonObj);

  // Define custom compare function for sorting
  const compareFunction = (a, b) => {
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
  };

  // Sort the entry array using the compare function
  entries.sort(compareFunction);

  // Create new JSON object from sorted array of key-value pairs
  const sortedObj = Object.fromEntries(entries);

  return sortedObj;
}

// Example usage:
const jsonObj = { b: 2, a: 1, c: 3 };
