// Assuming you have a 2D vector of QRGB colors named 'matrix'
// and its dimensions are stored in width and height

QImage matrixToImage(const QVector<QVector<QRgb>>& matrix, int width, int height) {
    QImage image(width, height, QImage::Format_ARGB32);

    for (int row = 0; row < height; ++row) {
        for (int col = 0; col < width; ++col) {
            image.setPixelColor(col, row, qRgb(matrix[row][col].r(), matrix[row][col].g(), matrix[row][col].b()));
